// Builds a short HTML alert for the admin and throttles repeated alerts.
const item = $input.first().json;
const execution = item.execution || {};
const trigger = item.trigger || {};
const workflow = item.workflow || {};
// Normal failures arrive under "execution"; failures of a trigger (no execution id) arrive under "trigger".
const error = execution.error || trigger.error || {};
const failedNode = execution.lastNodeExecuted || error.node?.name || (item.trigger ? 'Trigger' : 'unknown');

if (!/^-?\d+$/.test(String(item.admin_chat_id || ''))) {
  throw new Error('admin_chat_id غير مضبوط: ضع رقم محادثتك في عقدة 02 - Config');
}

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const cut = (v, n) => {
  const s = String(v ?? '');
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};

// Throttle: one alert per workflow + node every N minutes (static data persists in production runs).
const throttleMs = (Number(item.throttle_minutes) || 15) * 60 * 1000;
const key = `${workflow.id || 'unknown'}|${failedNode}`;
const store = $getWorkflowStaticData('global');
store.alerts = store.alerts || {};
const now = Date.now();
const prev = store.alerts[key] || { last: 0, suppressed: 0 };

// Remove keys not seen for 7 days so static data does not grow forever.
for (const k of Object.keys(store.alerts)) {
  if (now - store.alerts[k].last > 7 * 24 * 3600 * 1000) delete store.alerts[k];
}

if (prev.last && now - prev.last < throttleMs) {
  store.alerts[key] = { last: prev.last, suppressed: (prev.suppressed || 0) + 1 };
  return [];
}
store.alerts[key] = { last: now, suppressed: 0 };

const message = error.message || error.description || '';
const lines = [
  '⚠️ <b>خطأ في n8n</b>',
  `<b>Workflow:</b> ${esc(workflow.name)}`,
  `<b>العقدة:</b> ${esc(failedNode)}`,
  `<b>الخطأ:</b> ${esc(cut(message, 300))}`,
];
if (prev.suppressed > 0) lines.push(`🔁 تكرر ${prev.suppressed} مرة منذ آخر تنبيه`);
if (execution.url) lines.push(`<a href="${esc(execution.url)}">فتح التنفيذ #${esc(execution.id)}</a>`);

const tz = item.timezone || 'Asia/Gaza';
return [{
  json: {
    chat_id: String(item.admin_chat_id),
    text: lines.join('\n'),
    log: {
      timestamp: DateTime.now().setZone(tz).toISO(),
      workflow: cut(workflow.name, 100),
      level: 'error',
      message: cut(`${failedNode}: ${message}`, 500),
      ref: String(execution.id ?? ''),
    },
  },
}];
